using System;
using System.Linq;
using System.IO;
using System.Text;
using System.Drawing;
using System.Windows.Forms;
using System.Reflection;
using System.Collections.Generic;
namespace Ara {
 public static class BlockFeatureTests {
  static void Assert(bool yes,string reason){if(!yes)throw new Exception(reason);}
  static State New(){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,d);return s;}
  static CellBlock Work(Day d,string id,int minute,int count,decimal score=3,decimal satisfaction=2){var b=new CellBlock{Id=id,Start=d.Wake.Date.AddMinutes(minute),Count=count,Category="작업",Name="보고서",Score=score,Satisfaction=satisfaction};d.Records.Add(b);return b;}
  static PhoneCommand Command(MainForm f,string op,int first=60,int last=65,int lane=1){return new PhoneCommand{requestId=Guid.NewGuid().ToString("N"),op=op,date=f.Day.Date,lane=lane,first=first,last=last,baseRevision=f.PhoneSnapshot(f.Day.Date).revision};}
  public static void Run(Action<string,Action> check,string dir){
   check("satisfaction: legacy block without new field defaults to two and persists separately",()=>{var b=PhoneCodec.Read<CellBlock>(Encoding.UTF8.GetBytes("{\"Id\":\"old\",\"Score\":4}"));Assert(b.Satisfaction==2&&b.Score==4,"legacy default");b.Start=DateTime.Today;b.Satisfaction=5;var again=PhoneCodec.Read<CellBlock>(PhoneCodec.Json(b));Assert(again.Satisfaction==5&&again.Score==4,"separate persistence");});
   check("satisfaction: partial edit preserves focus and calculates time-weighted average",()=>{var s=New();var d=s.Days[0];var b=Work(d,"a",600,6,4,2);GridEngine.SetScore(d.Records,b.Start.AddMinutes(20),2,5,true);Assert(GridEngine.Total(d)==24&&d.Records.Sum(x=>x.Count)==6,"focus and time");Assert(GridEngine.SatisfactionAverage(d)==3&&d.Records.Count==3,"weighted average");GridEngine.SetScore(d.Records,d.Wake.AddHours(10),1,0,true);Assert(d.Records.Last().Satisfaction==0&&d.Records.Last().Score==0,"zero satisfaction valid");});
   check("merge: adjacent identical blocks combine across hours preserving both totals",()=>{var s=New();var d=s.Days[0];Work(d,"a",650,1,3,4);Work(d,"b",660,5,3,4);BlockTools.Merge(d.Records);Assert(d.Records.Count==1&&d.Records[0].Count==6&&d.Records[0].Id=="a"&&GridEngine.Total(d)==18&&GridEngine.SatisfactionAverage(d)==4,"combined facts");});
   check("merge: rating differences, gaps and distinct meals remain separate",()=>{var s=New();var d=s.Days[0];Work(d,"a",600,1,3,2);Work(d,"b",610,1,3,4);Work(d,"c",620,1,4,4);Work(d,"d",640,1,4,4);BlockTools.Merge(d.Records);Assert(d.Records.Count==4,"ratings and gaps");var a=new CellBlock{Id="m1",Start=d.Wake,Count=3,Category="식사",Name="식사",MealId="b1"};var b=a.Copy();b.Id="m2";b.Start=a.End;b.MealId="b6";var meals=new List<CellBlock>{a,b};BlockTools.Merge(meals);Assert(meals.Count==2,"distinct meal roles");});
   check("resize: actual duration can extend and shrink without changing ratings or identity",()=>{var s=New();var d=s.Days[0];var b=Work(d,"a",600,6,4,5);BlockTools.Resize(d.Records,"a",b.Start,9,d.Wake.Date,false);Assert(b.Count==9&&GridEngine.Total(d)==36&&b.Satisfaction==5,"extend");BlockTools.Resize(d.Records,"a",b.Start.AddMinutes(10),3,d.Wake.Date,false);Assert(b.Id=="a"&&b.Count==3&&b.Start.Minute==10&&GridEngine.Total(d)==12,"shrink start and end");});
   check("resize: collision rejected before changing any existing time or score",()=>{var s=New();var d=s.Days[0];var a=Work(d,"a",600,3);Work(d,"b",650,2,5,5);string before=Encoding.UTF8.GetString(PhoneCodec.Json(d.Records));bool blocked=false;try{BlockTools.Resize(d.Records,"a",a.Start,6,d.Wake.Date,false);}catch(InvalidOperationException){blocked=true;}Assert(blocked&&before==Encoding.UTF8.GetString(PhoneCodec.Json(d.Records)),"atomic collision");var clamped=BlockTools.Clamp(d.Records,a,1,"end",100,d.Wake.Date);Assert(clamped.Last==64,"stop before next block");});
   check("resize: planned meal start retains its prep and past actual facts",()=>{var s=New();var d=s.Days[0];var meal=d.GridBase.Single(x=>x.MealId=="b6");var prep=d.GridBase.Single(x=>x.PrepFor=="b6");var records=Encoding.UTF8.GetString(PhoneCodec.Json(d.Records));BlockTools.Resize(d.GridBase,meal.Id,meal.Start.AddMinutes(10),4,d.Wake.Date,true);Assert(prep.End==meal.Start&&meal.Count==4&&prep.Count==1,"prep follows start");Assert(records==Encoding.UTF8.GetString(PhoneCodec.Json(d.Records)),"actual untouched");});
   check("resize: phone command changes actual meal end, future floor, and keeps original upper meal",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"resize-meal.json")),s,true)){f.Show();Application.DoEvents();var meal=f.PhoneSnapshot(f.Day.Date).planned.Single(x=>x.mealId=="b1");var copy=Command(f,"copy",meal.start,meal.start+2);copy.sourceId=meal.id;var view=f.PhoneApply(copy);var original=view.planned.Single(x=>x.mealId=="b1");var c=Command(f,"resize",meal.start,meal.start+5);c.id=view.actual.Single().id;view=f.PhoneApply(c);Assert(view.actual.Single().count==6,"meal duration");Assert(view.planned.Single(x=>x.mealId=="b1").start==original.start&&view.planned.Single(x=>x.mealId=="b1").count==original.count,"upper historical meal frozen");var zone=f.GridPlan.Blocks.Single(x=>x.Category=="존2");Assert(zone.Start>=f.Day.Records.Single().End.AddHours(1),"future zone floor");f.Quit();}});
   check("satisfaction: changing score fragments leaves directly edited future plans fixed",()=>{var s=New();var d=s.Days[0];var meal=d.GridBase.Single(x=>x.MealId=="b1").Copy();meal.Id="eaten";d.Records.Add(meal);using(var f=new MainForm(new Store(Path.Combine(dir,"satisfaction-manual.json")),s,true)){f.Show();Application.DoEvents();var v=f.PhoneSnapshot(f.Day.Date);var zone=v.planned.Single(x=>x.category=="존2");var move=Command(f,"move",zone.start-1,zone.start-1,0);move.id=zone.id;f.PhoneApply(move);Assert(f.Day.ManualPlan,"manual state");var c=Command(f,"satisfaction",(int)((meal.Start-f.Day.Wake.Date).TotalMinutes/10),(int)((meal.Start-f.Day.Wake.Date).TotalMinutes/10));c.satisfaction=5;f.PhoneApply(c);Assert(f.Day.ManualPlan&&f.PhoneSnapshot(f.Day.Date).planned.Single(x=>x.id==zone.id).start==zone.start-1,"rating never reflows manual plan");f.Quit();}});
   check("categories: custom stable key, rename, color, order and hide preserve historical records",()=>{var s=New();CategoryCatalog.Save(s,"","독서","#336699",false,0);var category=s.CategorySettings[0];Work(s.Days[0],"a",600,2).Category=category.name;CategoryCatalog.Save(s,category.name,"책 읽기","#aa4488",true,3);Engine.Validate(s);var roundtrip=Store.Clone(s);Assert(roundtrip.Days[0].Records[0].Category==category.name&&roundtrip.CategorySettings[3].label=="책 읽기"&&roundtrip.CategorySettings[3].hidden,"stable meaning");Assert(!CategoryCatalog.Keys(roundtrip).Contains(category.name)&&CategoryCatalog.Caption(roundtrip.CategorySettings,roundtrip.Days[0].Records[0])=="보고서","hidden record remains");});
   check("categories: invalid color and duplicate visible names rejected without saving",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"category-invalid.json")),s,true)){f.Show();Application.DoEvents();var before=PhoneCodec.Hash(PhoneCodec.Json(f.Data));var c=Command(f,"category-save");c.name="추가";c.color="url(unsafe)";bool blocked=false;try{f.PhoneApply(c);}catch(InvalidDataException){blocked=true;}Assert(blocked&&before==PhoneCodec.Hash(PhoneCodec.Json(f.Data)),"invalid rejected atomically");f.Quit();}});
   check("categories: phone save synchronizes all dates and undo restores catalog",()=>{var s=New();using(var f=new MainForm(new Store(Path.Combine(dir,"category-sync.json")),s,true)){f.Show();Application.DoEvents();string other=f.Day.Wake.AddDays(-1).ToString("yyyy-MM-dd");var old=f.PhoneSnapshot(other);var c=Command(f,"category-save");c.name="독서";c.color="#336699";c.position=0;var view=f.PhoneApply(c);Assert(view.categorySettings[0].label=="독서"&&f.PhoneSnapshot(other).revision!=old.revision,"global CAS revision");var undo=Command(f,"undo");undo.sourceId=c.requestId;f.PhoneApply(undo);Assert(!f.Data.CategorySettings.Any(x=>x.label=="독서"),"catalog undo");f.Quit();}});
   check("phone retry: legacy hash schema remains compatible after added rating fields",()=>{var c=new PhoneCommand{op="score",date="2026-10-15",first=96,last=98,lane=1,requestId="retry",score=3};string legacy="{\"baseRevision\":\"\",\"category\":null,\"date\":\"2026-10-15\",\"first\":96,\"id\":null,\"lane\":1,\"last\":98,\"mealId\":null,\"name\":null,\"op\":\"score\",\"requestId\":\"retry\",\"score\":3,\"sourceId\":null}";Assert(PhoneCodec.CommandHash(c)==PhoneCodec.Hash(Encoding.UTF8.GetBytes(legacy)),"old duplicate retry hash");});
   check("color maps: increasing scores darken both ramps in light and dark without changing records",()=>{var s=New();var b=new CellBlock{Category="작업",Score=0,Satisfaction=0};foreach(bool dark in new[]{false,true}){Theme.Set(dark);foreach(string mode in new[]{"focus","satisfaction"}){float previous=1;for(int n=0;n<=5;n++){b.Score=n;b.Satisfaction=n;var color=CategoryCatalog.Fill(s.CategorySettings,b,mode,true);Assert(color.GetBrightness()<previous,"darker "+mode+" "+n);previous=color.GetBrightness();}}}Theme.Set(false);});
   check("PC: selected block end handle resizes across the next hour",()=>{var s=New();var d=s.Days[0];var b=Work(d,"handle",600,6);using(var f=new MainForm(new Store(Path.Combine(dir,"resize-handler.json")),s,true)){f.Show();Application.DoEvents();f.Board.Jump(b.Start);f.Board.SetSelection(new CellSelection{Lane=1,First=60,Last=65});var edge=f.Board.CellRect(1,65);var end=f.Board.CellRect(1,68);Action<string,MouseEventArgs> invoke=(name,e)=>typeof(Timetable).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f.Board,new object[]{e});invoke("OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,edge.Right-3,edge.Top+15,0));invoke("OnMouseMove",new MouseEventArgs(MouseButtons.Left,0,end.Left+end.Width/2,end.Top+15,0));invoke("OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,end.Left+end.Width/2,end.Top+15,0));Assert(f.Day.Records.Single().Count==9&&GridEngine.Total(f.Day)==27,"real handler saved resized block");f.ApplySatisfaction(4);Assert(f.Day.Records.Single().Satisfaction==4,"PC satisfaction handler");f.Quit();}});
  }
 }
}
